import React, {useState, useEffect} from "react";
import Config from "../scripts/config";
import { Link } from "react-router-dom";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const Callme = props => {
    let ros = null;
    const [isConnected, setIsConnected] = useState(false);

    const [values, setValues] = useState({
        email: ''
    })

    const navigate = useNavigate()
    axios.defaults.withCredentials = true;

    // connect to ROS when component is rendered
    useEffect(() => {
        ros = new window.ROSLIB.Ros();
        console.log("Da khoi tao duoc ros");

        ros.on("connection", () => {
            setIsConnected(true);
        });

        ros.on("close", () => {
            setIsConnected(false);

            // try to recconect every 3 seconds
            setTimeout(() => {
                try{
                    // this.state.ros.connect("ws://192.168.1.45:9090");
                    ros.connect(
                        "ws://" + 
                        Config.ROSBRIDGE_SERVER_IP +
                        ":" + 
                        Config.ROSBRIDGE_SERVER_PORT +
                        ""
                    );
                } catch (error) {
                    console.log("connection problem");
                }                
            }, Config.RECONNECTION_TIMER);
        });

        try{
            ros.connect(
                "ws://" + 
                Config.ROSBRIDGE_SERVER_IP +
                ":" + 
                Config.ROSBRIDGE_SERVER_PORT +
                ""
            );

        } catch (error) {
            console.log("connection problem");
        }
    }, []); //

    const handleCmdRequest = (event) => {
        event.preventDefault();
        // asign email recv to value
        // setEmail(props.email);
        console.log("Email nhận được từ body -> home:", props.email);

        setValues({
            ...values,
                email: props.email,
        })
        // send request to server

        axios.post("http://" + Config.ROSBRIDGE_SERVER_IP + ":" + Config.SERVER_PORT + "/callme", values)
            .then(res => {
                if(res.data.Status === "Success") {
                    console.log("recv data from server");
                    console.log(res.data.Data[0].x);

                    // send data to ros
                    // console.log("handle command cmdrequest");
                    var cmd_goal = new window.ROSLIB.Topic({
                        ros: ros,
                        name: Config.CMD_GOAL_TOPIC,
                        messageType: "move_base_msgs/MoveBaseActionGoal",
                    });

                    // create new twist message
                    var goal_data = new window.ROSLIB.Message({
                        goal: {
                            target_pose:{
                                header:{
                                    frame_id: "map",
                                },
                                pose:{
                                    position:{
                                        x: res.data.Data.x,
                                        y: res.data.Data.y,
                                        z: 0.0,
                                    },

                                    orientation: {
                                        x: 0.0,
                                        y: 0.0,
                                        z: res.data.Data.z,
                                        w: res.data.Data.w,
                                    },
                                },
                            },
                        },
                    })

                    // publish the message
                    cmd_goal.publish(goal_data);

                }

                else{
                    alert(res.data.Error);
                }
            })

    }

    return(
        <div>
            <button className="btn btn-info w-30 rounded-0" style={{ marginBottom: '20px' }} onClick={handleCmdRequest}>Call me</button>

        </div>
    );
}

export default Callme;
